// GENERATED by /protoflow-prototype from SCR-001 (booking-request) — edit the docs, not this file.
// Page type: Form — narrow booking form under the product nav; success goes to My bookings.
// (Shape reference for prototype/<feature>/<SCR-id>.js — not copied into engagements. Build with the ui.js kit; open items
//  from the docs are rendered automatically under the page from notes.js, so no ctx.note for them.)
import { appNav, appFooter, requireSignIn } from "../app.js";
import { pageHead, form, field, input, fieldError, btn, busy, emptyState, delay } from "../ui.js";

export default {
  id: "SCR-001",
  title: "Booking form",
  async render(root, ctx) {
    const { query, one, run, go, violate, ok, add } = ctx;
    if (requireSignIn(ctx)) return;                                         // signed-in-only page: redirect like the real app
    const rooms = query("select id, name from resources order by name");
    const room = input({ name: "resource_id", options: rooms.map(r => [r.id, r.name]) });
    const start = input({ name: "slot_start", type: "datetime-local", required: true });
    const end = input({ name: "slot_end", type: "datetime-local", required: true });
    const msg = ctx.h("div");
    const book = btn("Book room", null, { type: "submit", size: "lg", ref: "REQ-001" });

    async function submit() {                                               // FLOW-001 steps 1–3
      msg.replaceChildren();
      if (!fieldError(end, end.value && end.value > start.value ? "" : "The end time must be after the start time.")) return;
      const clash = one(                                                    // BR-002: no overlapping active booking
        "select id from bookings where resource_id = ? and status in ('hold','approved') and slot_start < ? and slot_end > ?",
        [room.value, end.value, start.value]);
      if (clash) return msg.append(violate("BR-002", "That room is already booked at this time — please pick another slot."));
      const done = busy(book, "Booking…");                                  // state: submitting
      await delay(500);
      run("insert into bookings(id, resource_id, status, slot_start, slot_end, created_at) values (?, ?, 'hold', ?, ?, datetime('now'))",
        [crypto.randomUUID(), room.value, start.value, end.value]);
      done();
      ok("Room held — we'll let you know once it's approved.");            // state: success
      go("SCR-003");
    }

    add(
      appNav(ctx, "book"),
      pageHead({ title: "Book a room", sub: "Choose a room and a time. We'll hold it while it's approved.", ref: "SCR-001" }),
      rooms.length
        ? form({ onsubmit: submit, ref: "FLOW-001" },
            field("Room", room), field("From", start), field("To", end, { help: "Bookings are in 30-minute steps." }),
            msg, ctx.h("div", { class: "actions" }, book, btn("Cancel", () => go("SCR-003"), { kind: "outline", size: "lg" })))
        : emptyState({ icon: "box", title: "No rooms to book yet", text: "Rooms appear here once they're added." }),   // state: empty
      appFooter(ctx));
  },
};
